#!/usr/bin/env bash
set -Eeuo pipefail

# ============================================================
# Chatix patch runner
#
# Usage:
#   chmod +x apply_chatix_changes.sh
#   ./apply_chatix_changes.sh
#
# Or:
#   CHATIX_ROOT=/path/to/chatix ./apply_chatix_changes.sh
# ============================================================

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CHATIX_ROOT:-$SCRIPT_DIR}"

cd "$PROJECT_ROOT"

echo "============================================================"
echo " Chatix changes runner"
echo " Project: $PROJECT_ROOT"
echo "============================================================"
echo

if [[ ! -f "pubspec.yaml" ]]; then
  echo "ERROR: pubspec.yaml не найден."
  echo "Положи этот скрипт в корень Flutter-проекта"
  echo "или запусти так:"
  echo "  CHATIX_ROOT=/полный/путь/к/chatix ./apply_chatix_changes.sh"
  exit 1
fi

command -v python3 >/dev/null 2>&1 || {
  echo "ERROR: python3 не установлен или не находится в PATH."
  exit 1
}

# Проверяем Flutter заранее, но не падаем — команды из исходного JSON
# сами содержат свою проверку analyze.
if command -v flutter >/dev/null 2>&1; then
  echo "Flutter: $(flutter --version 2>/dev/null | head -1)"
else
  echo "WARNING: flutter не найден в PATH."
  echo "После применения изменений можно будет отдельно выполнить flutter analyze."
fi
echo

# Если это git-репозиторий, создаём резервный patch до изменений.
if command -v git >/dev/null 2>&1 && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  BACKUP_PATCH="/tmp/chatix-before-patch-$(date +%Y%m%d-%H%M%S).patch"
  git diff --binary > "$BACKUP_PATCH" || true
  echo "Git backup patch: $BACKUP_PATCH"
else
  echo "Git repository не обнаружен — backup patch не создаётся."
fi

run_command() {
  local number="$1"
  local command_text="$2"

  # Исходный JSON жёстко использует /home/user/chatix.
  # Здесь заменяем его на реальный PROJECT_ROOT.
  command_text="${command_text//cd \/home\/user\/chatix/cd \"$PROJECT_ROOT\"}"

  echo
  echo "============================================================"
  echo " BLOCK $number / 20"
  echo "============================================================"

  bash -c "$command_text"
}

run_command 1 "$(printf '%s' '' | base64 -d)"
run_command 2 "$(printf '%s' '' | base64 -d)"
run_command 3 "$(printf '%s' '' | base64 -d)"
run_command 4 "$(printf '%s' '' | base64 -d)"
run_command 5 "$(printf '%s' '' | base64 -d)"
run_command 6 "$(printf '%s' '' | base64 -d)"
run_command 7 "$(printf '%s' '' | base64 -d)"
run_command 8 "$(printf '%s' '' | base64 -d)"
run_command 9 "$(printf '%s' '' | base64 -d)"
run_command 10 "$(printf '%s' '' | base64 -d)"
run_command 11 "$(printf '%s' '' | base64 -d)"
run_command 12 "$(printf '%s' '' | base64 -d)"
run_command 13 "$(printf '%s' '' | base64 -d)"
run_command 14 "$(printf '%s' '' | base64 -d)"
run_command 15 "$(printf '%s' '' | base64 -d)"
run_command 16 "$(printf '%s' '' | base64 -d)"
run_command 17 "$(printf '%s' '' | base64 -d)"
run_command 18 "$(printf '%s' '' | base64 -d)"
run_command 19 "$(printf '%s' '' | base64 -d)"
run_command 20 "$(printf '%s' '' | base64 -d)"

echo
echo "============================================================"
echo " Все блоки успешно выполнены."
echo "============================================================"
echo

if command -v flutter >/dev/null 2>&1; then
  echo "Запускаю финальную проверку:"
  echo "  flutter analyze"
  echo
  flutter analyze
else
  echo "Flutter не найден, поэтому flutter analyze пропущен."
  echo "После настройки Flutter выполни:"
  echo
  echo "  cd \"$PROJECT_ROOT\""
  echo "  flutter analyze"
fi

echo
echo "Готово."
